const ScreenAtlasCanvas = ({ savedForks, onSaveFork, askedForks, onOpenConversation, onOpenReflection }) => {
  const [selectedForkId, setSelectedForkId] = useState(null);
  const [dwellTime, setDwellTime] = useState(0);
  const [showPattern, setShowPattern] = useState(false);
  const [patternInsight, setPatternInsight] = useState("");
  const [bgImage, setBgImage] = useState(null);
  const [transform, setTransform] = useState({ x: 0, y: 0, scale: 1 });
  const [isDragging, setIsDragging] = useState(false);
  const [hoveredPathId, setHoveredPathId] = useState(null);

  useEffect(() => {
    const timer = setInterval(() => {
      setDwellTime(prev => {
        if (prev === 8) {
          callAIWithVS(
            "You are a pattern recognition engine. Analyze the forks a user has inspected and saved. Identify the underlying thematic thread and suggest similar unseen paths.",
            "Inspected forks: []. Saved forks: []. What is the common thread? Return a 1-sentence insight and 6 new path IDs."
          ).then(res => {
            setPatternInsight(res.text);
            setShowPattern(true);
          }).catch(() => {
            setPatternInsight("The forks you've inspected share a thread — alums who realized the data was the question. Want to see the other 6?");
            setShowPattern(true);
          });
        }
        return prev + 1;
      });
    }, 1000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    generateImage("Antique nautical chart aesthetic, ink on warm cream vellum, faint compass rose graticule, multiple intersecting trajectory lines radiating from a central node, no labels, deeply textured paper, suitable as a soft background behind UI")
      .then(url => { if (url) setBgImage(url); });
  }, []);

  const handlePointerDown = (e) => {
    setIsDragging(true);
    e.currentTarget.setPointerCapture(e.pointerId);
  };

  const handlePointerMove = (e) => {
    if (!isDragging) return;
    setTransform(prev => ({ ...prev, x: prev.x + e.movementX, y: prev.y + e.movementY }));
  };

  const handlePointerUp = (e) => {
    setIsDragging(false);
    e.currentTarget.releasePointerCapture(e.pointerId);
    callAIWithFallback("You are a cartographic salience engine. Determine which fork labels should be visible based on current zoom level, user dwell history, and 'open for conversation' status. Output valid JSON only.", "Zoom level: " + transform.scale).catch(() => {});
  };

  const handleWheel = (e) => {
    const scaleChange = e.deltaY * -0.001;
    const newScale = Math.min(Math.max(0.5, transform.scale + scaleChange), 3);
    setTransform(prev => ({ ...prev, scale: newScale }));
  };

  const selectedFork = SEED_FORKS.find(f => f.id === selectedForkId);
  const selectedPath = selectedFork ? SEED_PATHS.find(p => p.id === selectedFork.path_id) : null;

  const pathCoords = useMemo(() => {
    return SEED_PATHS.map((path, i) => {
      const angle = (i / SEED_PATHS.length) * Math.PI * 2;
      const nodes = path.forks.map((forkId, j) => {
        const radius = 100 + (j * 80) + (Math.random() * 20);
        const jitterAngle = angle + (Math.random() * 0.2 - 0.1);
        return {
          id: forkId,
          x: 400 + Math.cos(jitterAngle) * radius,
          y: 400 + Math.sin(jitterAngle) * radius,
          isSpecific: SPECIFIC_FORKS.some(sf => sf.id === forkId)
        };
      });
      return { id: path.id, nodes };
    });
  }, []);

  return (
    <article className="p-time-machine" style={{ position: 'relative', height: 'calc(100vh - 105px)', overflow: 'hidden', background: bgImage ? `url(${bgImage}) center/cover` : '#FDFBF7' }}>

      <div 
        style={{ width: '100%', height: '100%', cursor: isDragging ? 'grabbing' : 'grab', position: 'relative', overflow: 'hidden' }}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
        onWheel={handleWheel}
      >
        <motion.div style={{ width: '100%', height: '100%', transformOrigin: '0 0' }} animate={{ x: transform.x, y: transform.y, scale: transform.scale }} transition={{ type: 'tween', duration: 0 }}>
          <svg width="800" height="800" style={{ position: 'absolute', top: '50%', left: '50%', transform: 'translate(-50%, -50%)', overflow: 'visible' }}>
            <circle cx="400" cy="400" r="8" fill="var(--nu-text-primary)" />
            <text x="400" y="425" textAnchor="middle" className="nu-mono" fontSize="12" fill="var(--nu-text-secondary)">undeclared · first-gen</text>

            {pathCoords.map((path, i) => (
              <motion.g key={path.id} initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: i * 0.03, duration: 0.5 }}>
                <g onMouseEnter={() => setHoveredPathId(path.id)} onMouseLeave={() => setHoveredPathId(null)}>
                  <polyline 
                    points={`400,400 ${path.nodes.map(n => `${n.x},${n.y}`).join(' ')}`}
                    fill="none"
                    stroke={(selectedPath?.id === path.id || hoveredPathId === path.id) ? "var(--nu-accent)" : "rgba(11, 19, 38, 0.15)"}
                    strokeWidth={(selectedPath?.id === path.id || hoveredPathId === path.id) ? "2" : "1"}
                    style={{ transition: 'all 0.3s ease' }}
                  />
                  <polyline 
                    points={`400,400 ${path.nodes.map(n => `${n.x},${n.y}`).join(' ')}`}
                    fill="none"
                    stroke="transparent"
                    strokeWidth="16"
                    style={{ cursor: 'pointer' }}
                  />
                </g>
                {path.nodes.map(node => (
                  <g key={node.id} onClick={(e) => { e.stopPropagation(); setSelectedForkId(node.id); }} style={{ cursor: 'pointer' }}>
                    <circle 
                      cx={node.x} cy={node.y} 
                      r={selectedForkId === node.id ? "6" : node.isSpecific ? "4" : "3"} 
                      fill={selectedForkId === node.id ? "var(--nu-accent)" : node.isSpecific ? "var(--nu-text-primary)" : "rgba(11, 19, 38, 0.4)"}
                      style={{ transition: 'all 0.2s ease' }}
                    />
                    {node.isSpecific && selectedForkId !== node.id && (
                      <text x={node.x + 10} y={node.y + 4} className="nu-label" fontSize="11" fill="var(--nu-text-secondary)">
                        {SEED_FORKS.find(f => f.id === node.id)?.fork_label.substring(0, 20)}...
                      </text>
                    )}
                    {askedForks.includes(node.id) && (
                      <motion.foreignObject 
                        x={node.x - 12} y={node.y - 28} width="24" height="24"
                        initial={{ scale: 1.4, opacity: 0, rotate: -15 }} 
                        animate={{ scale: 1, opacity: 1, rotate: 0 }} 
                        transition={{ duration: 0.2 }}
                        style={{ pointerEvents: 'none' }}
                      >
