const ScreenConversationLaunch = ({ fork, path, onClose, onSuccess }) => {
  const [draftText, setDraftText] = useState("");
  const [isDrafting, setIsDrafting] = useState(true);
  const [isSending, setIsSending] = useState(false);
  const [isConfirmed, setIsConfirmed] = useState(false);
  const [error, setError] = useState(null);

  useEffect(() => {
    let isMounted = true;
    const draft = async () => {
      try {
        const res = await callAIWithVS(
          "You are an empathetic communication coach. Draft a short, curious icebreaker from a first-year student to an alum. Focus ONLY on the specific career turn the student tapped. Tone: curious, specific, never desperate. Max 60 words.",
          `Student context: Undeclared first-gen. Alum turn: ${fork.fork_label}, ${fork.paraphrased_reasoning}. Draft the message.`
        );
        if (!isMounted) return;

        // Simulate streaming effect for the UI
        const fullText = res.text.replace(/["']/g, ''); // clean up quotes
        let i = 0;
        const interval = setInterval(() => {
          setDraftText(fullText.slice(0, i));
          i++;
          if (i > fullText.length) {
            clearInterval(interval);
            setIsDrafting(false);
          }
        }, 14); // 14ms per char as per spec
      } catch (e) {
        if (isMounted) {
          setError("AI drafting failed. Please type your message.");
          setIsDrafting(false);
        }
      }
    };
    draft();
    return () => { isMounted = false; };
  }, [fork]);

  const handleSend = async () => {
    setIsSending(true);
    // Simulate Power Automate provisioning
    await new Promise(r => setTimeout(r, 2400));
    setIsSending(false);
    setIsConfirmed(true);
    if (onSuccess) onSuccess();
  };

  const alumFirstName = path.alum_name.split(' ')[0];

  return (
    <div className="p-chat" style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'flex-end', justifyContent: 'center', zIndex: 100 }}>
      <motion.div 
        initial={{ y: '100%' }} animate={{ y: 0 }} exit={{ y: '100%' }} transition={{ type: 'tween', ease: 'easeOut', duration: 0.32 }}
        style={{ width: '100%', maxWidth: '600px', background: 'var(--nu-bg)', borderTopLeftRadius: '8px', borderTopRightRadius: '8px', padding: '32px', boxShadow: '0 -8px 32px rgba(0,0,0,0.1)' }}
      >
        {!isConfirmed ? (
          <>
            <div className="nu-label" style={{ marginBottom: '16px', color: 'var(--nu-text-secondary)' }}>
              Drafting message to {alumFirstName}...
            </div>

            <div className="p-stream" style={{ position: 'relative', marginBottom: '24px' }}>
              <textarea 
                value={draftText}
                onChange={e => setDraftText(e.target.value)}
                disabled={isDrafting || isSending}
                style={{ height: '120px', resize: 'none', fontSize: '16px', lineHeight: 1.5 }}
                className={isDrafting ? 'streaming-highlight' : ''}
              />
              {error && <div className="nu-body" style={{ color: 'var(--nu-accent)', fontSize: '12px', marginTop: '8px' }}>{error}</div>}
            </div>

            <div className="p-hitl" style={{ background: 'var(--nu-surface)', padding: '16px', borderRadius: 'var(--radius-card)', display: 'flex', gap: '12px', marginBottom: '32px' }}>
              <lucide.Lock size={16} color="var(--nu-text-secondary)" style={{ flexShrink: 0, marginTop: '2px' }} />
              <div className="nu-mono" style={{ fontSize: '12px', color: 'var(--nu-text-secondary)' }}>
                {alumFirstName} will see your first name, your year, the fork you tapped, and your message.
              </div>
            </div>

            <div style={{ display: 'flex', gap: '16px' }}>
              <button className="btn-primary" style={{ flex: 1 }} onClick={handleSend} disabled={isDrafting || isSending || !draftText}>
                {isSending ? <lucide.Loader2 size={18} className="animate-spin" /> : 'Send Message'}
              </button>
              <button className="btn-ghost" onClick={onClose} disabled={isSending}>Cancel</button>
            </div>
          </>
        ) : (
          <div style={{ textAlign: 'center', padding: '32px 0' }}>
            <div style={{ width: '48px', height: '48px', borderRadius: '50%', background: 'var(--nu-success)', color: 'white', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 24px' }}>
              <lucide.Check size={24} />
            </div>
            <h3 className="nu-display" style={{ fontSize: '24px', margin: '0 0 16px 0' }}>Channel created</h3>
            <p className="nu-body" style={{ color: 'var(--nu-text-secondary)', marginBottom: '32px', lineHeight: 1.5 }}>
              echoes-{alumFirstName.toLowerCase()}-{fork.fork_category}. Your message has been posted. {alumFirstName} has 48 hours to respond — we'll suggest another Trailblazer if they don't.
            </p>
            <div style={{ display: 'flex', gap: '16px', justifyContent: 'center' }}>
              <button className="btn-primary" onClick={onClose}>Return to Atlas</button>
              <button className="btn-secondary">Open in Teams</button>
            </div>
          </div>
        )}
      </motion.div>
    </div>
  );
};

const ScreenReflectionJournal = ({ fork, onClose }) => {
  const [prompt, setPrompt] = useState("");
  const [text, setText] = useState("");
  const [status, setStatus] = useState("idle"); // idle, saving, saved

  useEffect(() => {
    callAIWithVS(
      "You are a thoughtful academic advisor. Generate a reflection prompt based on the career fork the student is looking at.",
      `Fork label: ${fork.fork_label}. Generate the prompt.`
    ).then(res => setPrompt(res.text)).catch(() => setPrompt("What are your thoughts on this career turn?"));
  }, [fork]);

  const handleSave = async () => {
    setStatus("saving");
    try {
      await callAIWithFallback("You are a CLR evidence extractor. Analyze the student's activity and reflection text against the CLR competency taxonomy. Extract evidence packets. STRICT FERPA BOUNDARIES: Output only structured tags, no PII. Output valid JSON only.", "Extract evidence.");
    } catch (e) {}
    setStatus("saved");
    setTimeout(onClose, 1500);
  };

  return (
    <div className="p-diary" style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 100 }}>
