// --- APP ROOT ---

const App = () => {
  const [currentScreen, setCurrentScreen] = useState('intake_form');
  const [activeModal, setActiveModal] = useState(null); // { type: 'conversation' | 'reflection', fork: object, path: object }
  const [savedForks, setSavedForks] = useState([]);
  const [askedForks, setAskedForks] = useState([]);
  const [flyingBookmarks, setFlyingBookmarks] = useState([]);

  const handleSaveFork = (e, forkId) => {
    if (!savedForks.includes(forkId)) {
      const rect = e.currentTarget.getBoundingClientRect();
      const id = Date.now();
      setFlyingBookmarks(prev => [...prev, { id, x: rect.left, y: rect.top }]);
      setTimeout(() => {
        setSavedForks(prev => [...prev, forkId]);
        setFlyingBookmarks(prev => prev.filter(b => b.id !== id));
      }, 600);
    }
  };

  const renderScreen = () => {
    switch (currentScreen) {
      case 'intake_form': return <ScreenIntakeForm onComplete={() => setCurrentScreen('atlas_canvas')} />;
      case 'atlas_canvas': return <ScreenAtlasCanvas 
        savedForks={savedForks} 
        onSaveFork={handleSaveFork} 
        askedForks={askedForks}
        onOpenConversation={(fork, path) => setActiveModal({ type: 'conversation', fork, path })} 
        onOpenReflection={(fork) => setActiveModal({ type: 'reflection', fork })} 
      />;
      case 'advisor_aggregate': return <ScreenAdvisorAggregate />;
      case 'alum_annotation_flow': return <ScreenAlumAnnotation />;
      default: return <div>Screen not found</div>;
    }
  };

  return (
    <div style={{ minHeight: '100vh', display: 'flex', flexDirection: 'column' }}>
      <GlobalStyles />
      <CostContainmentBanner />
      <Header />

      <main style={{ flex: 1, position: 'relative' }}>
        {renderScreen()}
      </main>

      <AnimatePresence>
        {activeModal?.type === 'conversation' && (
          <ScreenConversationLaunch 
            fork={activeModal.fork} 
            path={activeModal.path} 
            onClose={() => setActiveModal(null)} 
            onSuccess={() => setAskedForks(prev => [...prev, activeModal.fork.id])}
          />
        )}
        {activeModal?.type === 'reflection' && (
          <ScreenReflectionJournal fork={activeModal.fork} onClose={() => setActiveModal(null)} />
        )}
      </AnimatePresence>

      {flyingBookmarks.map(b => (
        <motion.div
          key={b.id}
          initial={{ x: b.x, y: b.y, scale: 1, opacity: 1 }}
          animate={{ x: 24, y: 100, scale: 0.5, opacity: 0 }}
          transition={{ duration: 0.6, ease: "circIn" }}
          style={{ position: 'fixed', zIndex: 9999, pointerEvents: 'none', color: 'var(--nu-accent)' }}
        >
          <lucide.Bookmark size={24} fill="currentColor" />
        </motion.div>
      ))}

      {/* Demo Controls */}
      <div style={{ position: 'fixed', bottom: 16, right: 16, zIndex: 9999, background: '#fff', border: '1px solid var(--nu-border)', padding: 8, borderRadius: 'var(--radius-card)', boxShadow: '0 4px 12px rgba(0,0,0,0.1)' }}>
        <select className="nu-mono" style={{ fontSize: '12px', padding: '4px 8px', width: 'auto' }} value={currentScreen} onChange={(e) => setCurrentScreen(e.target.value)}>
          <option value="intake_form">1. Intake Form</option>
          <option value="atlas_canvas">2. Atlas Canvas (Hero)</option>
          <option value="advisor_aggregate">3. Advisor Aggregate</option>
          <option value="alum_annotation_flow">4. Alum Annotation Flow</option>
        </select>
      </div>
    </div>
  );
};

function __test_state_transitions__() {
  console.assert(typeof App === 'function', 'App must be a component');
  return true;
}
if (typeof window !== 'undefined') {
  window.__hicProtoTests = __test_state_transitions__;
}

